> I think the nodeipam should handle finalizers correctly to node hand out the same podCIDR to multiple nodes.

yes, if the podCIDR is still in use it should not be released

/triage accepted

This seems as simple as

```diff
diff --git a/pkg/controller/nodeipam/ipam/range_allocator.go b/pkg/controller/nodeipam/ipam/range_allocator.go
index a79982a6db2..97ac56b94fd 100644
--- a/pkg/controller/nodeipam/ipam/range_allocator.go
+++ b/pkg/controller/nodeipam/ipam/range_allocator.go
@@ -270,7 +270,7 @@ func (r *rangeAllocator) syncNode(ctx context.Context, key string) error {
        // Check the DeletionTimestamp to determine if object is under deletion.
        if !node.DeletionTimestamp.IsZero() {
                logger.V(3).Info("node is being deleted", "node", key)
-               return r.ReleaseCIDR(logger, node)
+               return nil
        }
        return r.AllocateOrOccupyCIDR(ctx, node)
 }
```

